def _modern_truncate(text: str, max_length: int, tokens: list[str], separator: str) -> str:
    # Split text into runs of separators and words
    import re
    sep_re = re.escape(separator)
    pattern = f'({sep_re}+|[^ {sep_re}]+)'
    parts = re.findall(pattern, text)

    result_parts = []
    length = 0

    for part in parts:
        part_len = len(part)
        if length + part_len > max_length:
            # Truncate part to fit
            take = max_length - length
            if take > 0:
                result_parts.append(part[:take])
            break
        else:
            result_parts.append(part)
            length += part_len

    # Remove trailing separators
    while result_parts and result_parts[-1].endswith(separator):
        last = result_parts[-1]
        # Remove trailing separator runs
        while last.endswith(separator):
            last = last[:-len(separator)]
        if last:
            result_parts[-1] = last
            break
        else:
            result_parts.pop()

    return ''.join(result_parts)

